export function translate(locale:Locale,key:string):string{return supplementalDictionaries[locale][key]??supplementalDictionaries.en[key]??dictionaries[locale][key]??dictionaries.en[key]??key}
export const LocaleContext=createContext<Locale>('en');
export function useT(){const locale=useContext(LocaleContext);return useCallback((key:string)=>translate(locale,key),[locale])}
export function useLocale(){return useContext(LocaleContext)}
